begin;
with j as (select * from jsonb_to_recordset($law7d0041$[{"code_id":"KoAP_RF","article_number":"5.12","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от пяти тысяч до двадцати тысяч рублей; на должностных лиц - от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от ста тысяч до пятисот тысяч рублей. (В редакции Федерального закона от 09.03.2021 № 37-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от пяти тысяч до двадцати тысяч рублей; на должностных лиц - от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от ста тысяч до пятисот тысяч рублей. (В редакции Федерального закона от 09.03.2021 № 37-ФЗ)\n\n(Дополнение частью - Федеральный закон от 21.07.2005 № 93-ФЗ)\n\n(Статья в редакции Федерального закона от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.12. Изготовление, распространение или размещение агитационных материалов с нарушением требований законодательства о выборах и референдумах","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d6c74ff08543087489c0f427daea0b5cea19a21a3a71baf305eb1017cb02d397"},{"code_id":"KoAP_RF","article_number":"5.13","version_date":"2001-12-30","article_text":"Непредоставление до окончания срока предвыборной агитации возможности обнародовать (опубликовать) опровержение или иное разъяснение в защиту чести, достоинства или деловой репутации зарегистрированного кандидата, деловой репутации избирательного объединения в случае обнародования (опубликования) в средствах массовой информации материалов, способных нанести ущерб чести, достоинству или деловой репутации зарегистрированного кандидата, деловой репутации избирательного объединения, если в соответствии с федеральным законом предоставление такой возможности является обязательным, -   (В редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц в размере от двух тысяч до трех тысяч рублей; на юридических лиц - от десяти тысяч до двадцати тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.13. Непредоставление возможности обнародовать опровержение или иное разъяснение в защиту чести, достоинства или деловой репутации","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"295992ad79ac74e29f4c45b6090e15bb547d96cffc0810c7b2229b74bd24343f"},{"code_id":"KoAP_RF","article_number":"5.14","version_date":"2001-12-30","article_text":"(Наименование в редакции федеральных законов от 09.03.2016 № 66-ФЗ, от 01.04.2020 № 90-ФЗ)\n\nУмышленное уничтожение или повреждение информационного материала, относящегося к выборам, референдуму, общероссийскому голосованию, либо агитационного материала, размещенного в соответствии с законом, вывешенного на здании, сооружении или ином объекте в период избирательной кампании, кампании референдума или в период подготовки и проведения общероссийского голосования, либо нанесение надписей или изображений на такой материал - (В редакции федеральных законов от 09.03.2016 № 66-ФЗ, от 01.04.2020 № 90-ФЗ)\n\nвлечет наложение административного штрафа в размере от пятисот до одной тысячи рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.14. Умышленное уничтожение или повреждение агитационного материала либо информационного материала, относящегося к выборам, референдуму, общероссийскому голосованию","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13c82be5e5afe589e5b873e6596f6a696b60e4a8c161005a5c1582c44350b943"},{"code_id":"KoAP_RF","article_number":"5.15","version_date":"2001-12-30","article_text":"1. Нарушение установленных законодательством о выборах и референдумах порядка и сроков уведомления избирательной комиссии о факте предоставления зарегистрированному кандидату, избирательному объединению, инициативной группе по проведению референдума, иной группе участников референдума для встреч с избирателями, участниками референдума помещения, находящегося в государственной или муниципальной собственности либо в собственности организации, в уставном (складочном) капитале которой доля (вклад) Российской Федерации, субъектов Российской Федерации и (или) муниципальных образований превышает 30 процентов на день официального опубликования (публикации) решения о назначении выборов, официального опубликования решения о назначении референдума, об условиях, на которых помещение было предоставлено, а также о том, когда это помещение может быть предоставлено в течение агитационного периода другим зарегистрированным кандидатам, избирательным объединениям, инициативной группе по проведению референдума, иным группам участников референдума, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двух тысяч до трех тысяч рублей.\n\n2. Нарушение установленного законодательством о выборах и референдумах права зарегистрированного кандидата, избирательного объединения, инициативной группы по проведению референдума, иной группы участников референдума на предоставление для встреч с избирателями, участниками референдума помещения, находящегося в государственной или муниципальной собственности либо в собственности организации, в уставном (складочном) капитале которой доля (вклад) Российской Федерации, субъектов Российской Федерации и (или) муниципальных образований превышает 30 процентов на день официального опубликования (публикации) решения о назначении выборов, официального опубликования решения о назначении референдума, или нарушение равных условий предоставления такого помещения -\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч до пяти тысяч рублей.\n\n(Статья в редакции Федерального закона от 27.07.2010 № 222-ФЗ)","article_title":"Статья 5.15. Нарушение установленных законодательством о выборах и референдумах порядка и сроков уведомления избирательной комиссии о факте предоставления помещений и права на предоставление помещений для встреч с избирателями, участниками референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"23b7adaea714bda86d343055362631d48b7275fa053e00e4faccf170e18e024f"},{"code_id":"KoAP_RF","article_number":"5.16","version_date":"2001-12-30","article_text":"Подкуп избирателей, участников референдума, если эти действия не содержат уголовно наказуемого деяния, либо осуществление благотворительной деятельности с нарушением законодательства о выборах и референдумах -\n\nвлечет наложение административного штрафа на граждан в размере от двадцати тысяч до двадцати пяти тысяч рублей; на должностных лиц - от тридцати тысяч до сорока тысяч рублей; на юридических лиц - от трехсот тысяч до пятисот тысяч рублей. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ; от 24.11.2014 № 355-ФЗ)\n\n(Статья в редакции Федерального закона от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.16. Подкуп избирателей, участников референдума либо осуществление в период избирательной кампании, кампании референдума благотворительной деятельности с нарушением законодательства о выборах и референдумах","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"04bd449eda33424bb6f1bdee63a0321be9fc722639680ea1e90979b65818eb62"},{"code_id":"KoAP_RF","article_number":"5.17","version_date":"2001-12-30","article_text":"влечет наложение административного штрафа на кандидата, на лицо, являвшееся кандидатом, на лицо, избранное депутатом или на иную выборную должность, на уполномоченного представителя по финансовым вопросам избирательного объединения, инициативной группы по проведению референдума, иной группы участников референдума, на должностное лицо кредитной организации в размере от двадцати тысяч до двадцати пяти тысяч рублей. (В редакции федеральных законов от 21.07.2005 № 93-ФЗ; от 22.06.2007 № 116-ФЗ; от 24.11.2014 № 355-ФЗ)\n\nне предусмотренное законом неполное предоставление либо несвоевременное предоставление председателем избирательной комиссии, комиссии референдума в средства массовой информации для опубликования сведений о поступлении и расходовании средств избирательных фондов, фондов референдума либо финансовых отчетов кандидатов, зарегистрированных кандидатов, избирательных объединений - (В редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nвлечет наложение административного штрафа в размере от десяти тысяч до двадцати тысяч рублей. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ; от 24.11.2014 № 355-ФЗ)\n\n(Статья в редакции Федерального закона от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.17. Непредоставление или неопубликование отчета, сведений о поступлении и расходовании средств, выделенных на подготовку и проведение выборов, референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2099db26ebc9b08ac9c6be3d1d8c2ce0cc5bda8c4ee75bf0833b2ff98070d07c"},{"code_id":"KoAP_RF","article_number":"5.18","version_date":"2001-12-30","article_text":"Использование кандидатом, избирательным объединением, инициативной группой по проведению референдума, иной группой участников референдума при финансировании своей избирательной кампании или кампании референдума денежных средств, не перечисленных в избирательный фонд, фонд референдума, или денежных средств, поступивших в избирательный фонд, фонд референдума с нарушением законодательства о выборах и референдумах, а равно расходование иными лицами в целях достижения определенного результата на выборах, референдуме денежных средств, не перечисленных в избирательный фонд, фонд референдума, если эти действия не содержат уголовно наказуемого деяния, либо превышение установленных законом предельных размеров расходования средств избирательного фонда, фонда референдума, либо расходование денежных средств избирательного фонда, фонда референдума на не предусмотренные законодательством о выборах и референдумах цели -\n\nвлечет наложение административного штрафа на граждан в размере от двадцати тысяч до двадцати пяти тысяч рублей; на должностных лиц - от тридцати тысяч до сорока тысяч рублей; на юридических лиц - от трехсот тысяч до одного миллиона рублей. (В редакции Федерального закона от 24.11.2014 № 355-ФЗ)\n\n(Статья в редакции Федерального закона от 21.07.2005 № 93-ФЗ)","article_title":"Статья 5.18. Незаконное использование денежных средств при финансировании избирательной кампании кандидата, избирательного объединения, деятельности инициативной группы по проведению референдума, иной группы участников референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"152b6e0778d85d62848b845fcc4f4d4a50f8cba62583448e0319a390a8d07989"},{"code_id":"KoAP_RF","article_number":"5.19","version_date":"2001-12-30","article_text":"Использование в ходе проведения избирательной кампании, подготовки и проведения референдума в целях достижения определенного результата на выборах, референдуме без компенсации за счет средств соответствующего избирательного фонда, фонда референдума материальной поддержки, оказанной гражданами, юридическими лицами, их филиалами, представительствами и иными подразделениями юридических лиц, за исключением использования избирательным объединением, выдвинувшим список кандидатов, без оплаты из средств избирательного фонда недвижимого и движимого имущества (за исключением ценных бумаг, печатной продукции и расходных материалов), находящегося в его пользовании на день официального опубликования (публикации) решения о назначении выборов, а также использование анонимной материальной поддержки, если эти действия не содержат уголовно наказуемого деяния, - (В редакции Федерального закона от 24.11.2014 № 355-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от двадцати тысяч до двадцати пяти тысяч рублей с конфискацией предмета административного правонарушения; на должностных лиц - от тридцати тысяч до сорока тысяч рублей с конфискацией предмета административного правонарушения; на юридических лиц - от ста тысяч до двухсот тысяч рублей с конфискацией предмета административного правонарушения. (В редакции Федерального закона от 24.11.2014 № 355-ФЗ)\n\n(Статья в редакции Федерального закона от 21.07.2005 № 93-ФЗ)","article_title":"Статья 5.19. Использование незаконной материальной поддержки при финансировании избирательной кампании, кампании референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6a72719c62559bb145db3069adad910c5153474b6e7a6cda111c43db4686249d"},{"code_id":"KoAP_RF","article_number":"5.2","version_date":"2001-12-30","article_text":"(Статья утратила силу - Федеральный закон от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.2. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4d0abf3ac75f9b8d8714eb27b87de03d1d6d1f60b336531dfdfc6da9692a1c0c"},{"code_id":"KoAP_RF","article_number":"5.20","version_date":"2001-12-30","article_text":"(Наименование в редакции федеральных законов от 21.07.2005 № 93-ФЗ; от 24.11.2014 № 355-ФЗ)\n\nОказание финансовой поддержки избирательной кампании кандидата, избирательного объединения, деятельности инициативной группы по проведению референдума, иной группы участников референдума помимо их избирательных фондов, фондов референдума, либо бесплатные или по необоснованно заниженным (завышенным) расценкам выполнение работ, оказание услуг, реализация товаров юридическими лицами, их филиалами, представительствами и иными подразделениями, связанных с проведением выборов, референдума и направленных на достижение определенного результата на выборах, на выдвижение инициативы проведения референдума, на достижение определенного результата на референдуме, либо выполнение оплачиваемых работ, реализация товаров, оказание платных услуг, направленных на достижение определенного результата на выборах, на выдвижение инициативы проведения референдума, на достижение определенного результата на референдуме без документально подтвержденного согласия кандидата или его уполномоченного представителя по финансовым вопросам, уполномоченного представителя по финансовым вопросам избирательного объединения, инициативной группы по проведению референдума, иной группы участников референдума и без оплаты из соответствующего избирательного фонда, фонда референдума, либо внесение пожертвований в избирательный фонд, фонд референдума через подставных лиц, либо оказание кандидату, инициативной группе по проведению референдума, иной группе участников референдума для проведения соответствующей избирательной кампании, кампании референдума материальной поддержки, направленной на достижение определенного результата на выборах, референдуме, без компенсации за счет средств соответствующего избирательного фонда, фонда референдума, если эти действия не содержат уголовно наказуемого деяния, - (В редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от десяти тысяч до пятнадцати тысяч рублей; на должностных лиц - от двадцати тысяч до тридцати тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот тысяч рублей с конфискацией предмета административного правонарушения. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ; от 24.11.2014 № 355-ФЗ)\n\n(Статья в редакции Федерального закона от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.20. Незаконное финансирование избирательной кампании кандидата, избирательного объединения, кампании референдума, оказание запрещенной законом материальной поддержки, связанные с проведением выборов, референдума выполнение работ, оказание услуг, реализация товаров бесплатно или по необоснованно заниженным (завышенным) расценкам","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6a34de2617312eae0a492df605f6e8911529aff88eecb9e7d74096556f5512bb"},{"code_id":"KoAP_RF","article_number":"5.21","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nНеперечисление, а равно перечисление в неполном объеме или с нарушением установленных законом сроков органом исполнительной власти, органом местного самоуправления, наделенными соответствующими полномочиями по перечислению средств, кредитной организацией, отделением связи средств избирательным комиссиям, комиссиям референдума, кандидатам, избирательным объединениям, инициативным группам по проведению референдума, иным группам участников референдума -  (В редакции федеральных законов от 21.07.2005 № 93-ФЗ; от 09.03.2016 № 66-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ; от 24.11.2014 № 355-ФЗ)\n\n(Статья в редакции Федерального закона от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.21. Несвоевременное перечисление средств избирательным комиссиям, комиссиям референдума, кандидатам, избирательным объединениям, инициативным группам по проведению референдума, иным группам участников референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c482b5ac250daf84264109a874bbd3a62040b3c446241228c242d594611d9384"},{"code_id":"KoAP_RF","article_number":"5.22","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 01.04.2020 № 90-ФЗ)\n\nвлечет наложение административного штрафа в размере тридцати тысяч рублей.\n\nвлечет наложение административного штрафа в размере тридцати тысяч рублей.\n\nвлечет наложение административного штрафа в размере пятидесяти тысяч рублей.\n\n(Статья в редакции Федерального закона от 01.06.2017 № 104-ФЗ)","article_title":"Статья 5.22. Незаконные выдача и получение избирательного бюллетеня, бюллетеня для голосования на референдуме, бюллетеня для общероссийского голосования","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"121931ea6fba9b57972022f87e3df63336f753127c2638d34fa1aef3da884a0f"},{"code_id":"KoAP_RF","article_number":"5.23","version_date":"2001-12-30","article_text":"Сокрытие остатков тиражей избирательных бюллетеней, бюллетеней для голосования на референдуме -\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи пятисот до двух тысяч пятисот рублей; на должностных лиц - от трех тысяч до четырех тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Статья в редакции Федерального закона от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.23. Сокрытие остатков тиражей избирательных бюллетеней, бюллетеней для голосования на референдуме","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9962604e9d13f1d81b916f2c0dc46b25476b1d5a27744c51144f9d308e156656"},{"code_id":"KoAP_RF","article_number":"5.24","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 01.04.2020 № 90-ФЗ)\n\nвлечет наложение административного штрафа в размере от пятисот до одной тысячи пятисот рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\nвлечет наложение административного штрафа в размере от одной тысячи пятисот до двух тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Статья в редакции Федерального закона от 21.07.2005 № 93-ФЗ)","article_title":"Статья 5.24. Нарушение установленного законом порядка подсчета голосов, определения результатов выборов, референдума, общероссийского голосования, порядка составления протокола об итогах голосования с отметкой \"Повторный\" или \"Повторный подсчет голосов\"","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3ec2beb5ca945130d4f02320d40f172283d68983cafe34aaefbca546278fe772"},{"code_id":"KoAP_RF","article_number":"5.25","version_date":"2001-12-30","article_text":"влечет наложение административного штрафа в размере от пятисот до одной тысячи рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\nвлечет наложение административного штрафа в размере от одной тысячи до двух тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\nвлечет наложение административного штрафа в размере от двух тысяч до трех тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\nвлечет наложение административного штрафа в размере от трех тысяч до четырех тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\nвлечет наложение административного штрафа в размере от четырех тысяч до пяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.25. Непредоставление сведений об итогах голосования или о результатах выборов","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ac1731b0a0a1d5c5ca99ab8e06eb07c73c3dc2d4aa49e01897cf4296abc7b6f2"},{"code_id":"KoAP_RF","article_number":"5.26","version_date":"2001-12-30","article_text":"1. Воспрепятствование осуществлению права на свободу совести и свободу вероисповедания, в том числе принятию религиозных или иных убеждений или отказу от них, вступлению в религиозное объединение или выходу из него, -\n\nвлечет наложение административного штрафа на граждан в размере от десяти тысяч до тридцати тысяч рублей; на должностных лиц - от пятидесяти тысяч до ста тысяч рублей; на юридических лиц - от ста тысяч до одного миллиона рублей. (В редакции Федерального закона от 06.07.2016 № 374-ФЗ)\n\n2. Умышленное публичное осквернение религиозной или богослужебной литературы, предметов религиозного почитания, знаков или эмблем мировоззренческой символики и атрибутики либо их порча или уничтожение -\n\nвлечет наложение административного штрафа на граждан в размере от тридцати тысяч до пятидесяти тысяч рублей либо обязательные работы на срок до ста двадцати часов; на должностных лиц - от ста тысяч до двухсот тысяч рублей.\n\n3. Осуществление религиозной организацией деятельности без указания своего официального полного наименования, в том числе выпуск или распространение в рамках миссионерской деятельности литературы, печатных, аудио- и видеоматериалов без маркировки с указанным наименованием или с неполной либо заведомо ложной маркировкой, -\n\nвлечет наложение административного штрафа в размере от тридцати тысяч до пятидесяти тысяч рублей с конфискацией литературы, печатных, аудио- и видеоматериалов.\n\n(Дополнение частью - Федеральный закон от 06.07.2016 № 374-ФЗ)\n\n4. Осуществление миссионерской деятельности с нарушением требований законодательства о свободе совести, свободе вероисповедания и о религиозных объединениях -\n\nвлечет наложение административного штрафа на граждан в размере от пяти тысяч до пятидесяти тысяч рублей; на юридических лиц - от ста тысяч до одного миллиона рублей.\n\n(Дополнение частью - Федеральный закон от 06.07.2016 № 374-ФЗ)\n\n5. Нарушение, предусмотренное частью 4 настоящей статьи, совершенное иностранным гражданином или лицом без гражданства, -\n\nвлечет наложение административного штрафа в размере от тридцати тысяч до пятидесяти тысяч рублей с административным выдворением за пределы Российской Федерации или без такового.\n\n(Дополнение частью - Федеральный закон от 06.07.2016 № 374-ФЗ)\n\n(Статья в редакции Федерального закона от 29.06.2013 № 136-ФЗ)","article_title":"Статья 5.26. Нарушение законодательства о свободе совести, свободе вероисповедания и о религиозных объединениях","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ef6e0f5d4f5705fa6a43896a195b3402c09877bb1bed8c157c2d2e4c6ee157a4"},{"code_id":"KoAP_RF","article_number":"5.27","version_date":"2001-12-30","article_text":"1. Нарушение трудового законодательства и иных нормативных правовых актов, содержащих нормы трудового права, если иное не предусмотрено частями 3, 4 и 6 настоящей статьи и статьей 5.271 настоящего Кодекса, -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от одной тысячи до пяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от одной тысячи до пяти тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей.\n\n2. Совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, лицом, ранее подвергнутым административному наказанию за аналогичное административное правонарушение, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от десяти тысяч до двадцати тысяч рублей или дисквалификацию на срок от одного года до трех лет; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от десяти тысяч до двадцати тысяч рублей; на юридических лиц - от пятидесяти тысяч до семидесяти тысяч рублей.\n\n3. Фактическое допущение к работе лицом, не уполномоченным на это работодателем, в случае, если работодатель или его уполномоченный на это представитель отказывается признать отношения, возникшие между лицом, фактически допущенным к работе, и данным работодателем, трудовыми отношениями (не заключает с лицом, фактически допущенным к работе, трудовой договор), -\n\nвлечет наложение административного штрафа на граждан в размере от трех тысяч до пяти тысяч рублей; на должностных лиц - от десяти тысяч до двадцати тысяч рублей.\n\n4. Уклонение от оформления или ненадлежащее оформление трудового договора либо заключение гражданско-правового договора, фактически регулирующего трудовые отношения между работником и работодателем, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от десяти тысяч до двадцати тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пяти тысяч до десяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n5. Совершение административных правонарушений, предусмотренных частью 3 или 4 настоящей статьи, лицом, ранее подвергнутым административному наказанию за аналогичное административное правонарушение, -\n\nвлечет наложение административного штрафа на граждан в размере пяти тысяч рублей; на должностных лиц - дисквалификацию на срок от одного года до трех лет; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от тридцати тысяч до сорока тысяч рублей; на юридических лиц - от ста тысяч до двухсот тысяч рублей.\n\n6. Невыплата или неполная выплата в установленный срок заработной платы, других выплат, осуществляемых в рамках трудовых отношений, если эти действия не содержат уголовно наказуемого деяния, либо воспрепятствование работодателем осуществлению работником права на замену кредитной организации, в которую должна быть переведена заработная плата, либо установление заработной платы в размере менее размера, предусмотренного трудовым законодательств\n\nом, - (В редакции Федерального закона от 26.07.2019 № 221-ФЗ)\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от десяти тысяч до двадцати тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от одной тысячи до пяти тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей.\n\n7. Совершение административного правонарушения, предусмотренного частью 6 настоящей статьи, лицом, ранее подвергнутым административному наказанию за аналогичное правонарушение, если эти действия не содержат уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до тридцати тысяч рублей или дисквалификацию на срок от одного года до трех лет; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от десяти тысяч до тридцати тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n(Статья в редакции Федерального закона от 03.07.2016 № 272-ФЗ)","article_title":"Статья 5.27. Нарушение трудового законодательства и иных нормативных правовых актов, содержащих нормы трудового права","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4654483e32b798203a0fe1f59e730bf899170629e2b76f755678c9e0bb658960"},{"code_id":"KoAP_RF","article_number":"5.271","version_date":"2001-12-30","article_text":"влечет предупреждение или наложение административного штрафа на должностных лиц в размере от двух тысяч до пяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от двух тысяч до пяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до восьмидесяти тысяч рублей.\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от пяти тысяч до десяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пяти тысяч до десяти тысяч рублей; на юридических лиц - от шестидесяти тысяч до восьмидесяти тысяч рублей.\n\nвлечет наложение административного штрафа на должностных лиц в размере от пятнадцати тысяч до двадцати пяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятнадцати тысяч до двадцати пяти тысяч рублей; на юридических лиц - от ста десяти тысяч до ста тридцати тысяч рублей.\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до тридцати тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от двадцати тысяч до тридцати тысяч рублей; на юридических лиц - от ста тридцати тысяч до ста пятидесяти тысяч рублей.\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до сорока тысяч рублей или дисквалификацию на срок от одного года до трех лет; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от тридцати тысяч до сорока тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от ста тысяч до двухсот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\nПримечание. Под средствами индивидуальной защиты в части 4 настоящей статьи следует понимать средства индивидуальной защиты, отнесенные техническим регламентом Таможенного союза \"О безопасности средств индивидуальной защиты\" ко 2 классу в зависимости от степени риска причинения вреда работнику.\n\n(Дополнение статьей - Федеральный закон от 28.12.2013 № 421-ФЗ)","article_title":"Статья 5.271. Нарушение государственных нормативных требований охраны труда, содержащихся в федеральных законах и иных нормативных правовых актах Российской Федерации","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e323dd80578b707a85968941b2d25804412841d6c993aca09bcd38d94ad59a81"},{"code_id":"KoAP_RF","article_number":"5.272","version_date":"2001-12-30","article_text":"Осуществление деятельности по трудоустройству граждан Российской Федерации за пределами территории Российской Федерации для работы на судах, плавающих под флагом иностранного государства, с нарушением предусмотренных законодательством Российской Федерации требований к осуществлению такой деятельности -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до четырех тысяч рублей; на должностных лиц - от тридцати пяти тысяч до сорока тысяч рублей; на юридических лиц - от четырехсот тысяч до пятисот тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 09.11.2024 № 378-ФЗ)","article_title":"Статья 5.272. Нарушение требований законодательства Российской Федерации при осуществлении деятельности по трудоустройству граждан Российской Федерации за пределами территории Российской Федерации для работы на судах, плавающих под флагом иностранного государства","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ffe1d8e15fb8d32ed6eec5d1c295b53653b4c96a36c04a89085e900a915e7f4a"},{"code_id":"KoAP_RF","article_number":"5.28","version_date":"2001-12-30","article_text":"Уклонение работодателя или лица, его представляющего, от участия в переговорах о заключении, об изменении или о дополнении коллективного договора, соглашения либо нарушение установленного законом срока проведения переговоров, а равно необеспечение работы комиссии по заключению коллективного договора, соглашения в определенные сторонами сроки -\n\nвлечет предупреждение или наложение административного штрафа в размере от одной тысячи до трех тысяч рублей. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ; от 27.07.2010 № 239-ФЗ)","article_title":"Статья 5.28. Уклонение от участия в переговорах о заключении коллективного договора, соглашения либо нарушение установленного срока их заключения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"382dd50fde78f855ce9f7d1c2e3f0f365a875181bc07796f7da62c0980580445"},{"code_id":"KoAP_RF","article_number":"5.29","version_date":"2001-12-30","article_text":"Непредоставление работодателем или лицом, его представляющим, в срок, установленный законом, информации, необходимой для проведения коллективных переговоров и осуществления контроля за соблюдением коллективного договора, соглашения, -\n\nвлечет предупреждение или наложение административного штрафа в размере от одной тысячи до трех тысяч рублей. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ; от 27.07.2010 № 239-ФЗ)","article_title":"Статья 5.29. Непредоставление информации, необходимой для проведения коллективных переговоров и осуществления контроля за соблюдением коллективного договора, соглашения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9e3594f13e2d501b343b19f2d8b9afaf168d3ba359eb4093ec6c5471c40e02fc"},{"code_id":"KoAP_RF","article_number":"5.3","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального за\n\nкона от 21.07.2005 № 93-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц в размере от одной тысячи до двух тысяч рублей; на юридических лиц - от десяти тысяч до двадцати тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц в размере от одной тысячи до одной тысячи пятисот рублей; на юридических лиц - от десяти тысяч до пятнадцати тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение частью - Федеральный закон от 21.07.2005 № 93-ФЗ)","article_title":"Статья 5.3. Неисполнение решения избирательной комиссии, комиссии референдума. Непредставление сведений и материалов по запросу избирательной комиссии, комиссии референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2d4662e9924b7a9e51f1261de94e774ca16dc84dc56383c0d0c94be07ad247f5"},{"code_id":"KoAP_RF","article_number":"5.30","version_date":"2001-12-30","article_text":"Необоснованный отказ работодателя или лица, его представляющего, от заключения коллективного договора, соглашения -\n\nвлечет предупреждение или наложение административного штрафа в размере от трех тысяч до пяти тысяч рублей. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ; от 27.07.2010 № 239-ФЗ)","article_title":"Статья 5.30. Необоснованный отказ от заключения коллективного договора, соглашения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2221b6395a5b22f38e315b1c55805ee4d878710bc58628e1732b77ac11fcf615"},{"code_id":"KoAP_RF","article_number":"5.31","version_date":"2001-12-30","article_text":"1. Нарушение или невыполнение работодателем или лицом, его представляющим, обязательств по коллективному договору, соглашению, за исключением случаев, предусмотренных частью 2 настоящей статьи, -\n\nвлечет предупреждение или наложение административного штрафа в размере от трех тысяч до пяти тысяч рублей.\n\n2. Нарушение или невыполнение работодателем или лицом, его представляющим, обязательств по коллективному договору, соглашению в части, касающейся охраны труда работников, занятых на работах с вредными и (или) опасными условиями труда, в том числе на подземных работах, -\n\nвлечет предупреждение или наложение административного штрафа в размере от шести тысяч до десяти тысяч рублей.\n\n(Статья в редакции Федерального закона от 27.11.2023 № 559-ФЗ)","article_title":"Статья 5.31. Нарушение или невыполнение обязательств по коллективному договору, соглашению","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b20b7d195f9f09190036d6520e7b8df2e4aa1a691a8ddafaedcc3ee6b1e0b3e0"},{"code_id":"KoAP_RF","article_number":"5.32","version_date":"2001-12-30","article_text":"Уклонение работодателя или его представителя от получения требований работников и от участия в примирительных процедурах, в том числе непредоставление помещения для проведения собрания (конференции) работников в целях выдвижения требований или создание препятствий проведению такого собрания (такой конференции), -\n\nвлечет наложение административного штрафа в размере от одной тысячи до трех тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.32. Уклонение от получения требований работников и от участия в примирительных процедурах","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"15d5f0f0686608e9f0001a89d8531fbd0c99e57b64c021e4c1d872b946660526"},{"code_id":"KoAP_RF","article_number":"5.33","version_date":"2001-12-30","article_text":"Невыполнение работодателем или его представителем обязательств по соглашению, достигнутому в результате примирительной процедуры, -\n\nвлечет наложение административного штрафа в размере от двух тысяч до четырех тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.33. Невыполнение соглашения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c3fed35f7ce15f45cce71784583fbbe23dd2cecaa3bc07186dc39624fae0b5c"},{"code_id":"KoAP_RF","article_number":"5.34","version_date":"2001-12-30","article_text":"Увольнение работников в связи с коллективным трудовым спором и объявлением забастовки -\n\nвлечет наложение административного штрафа в размере от четырех тысяч до пяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.34. Увольнение работников в связи с коллективным трудовым спором и объявлением забастовки","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3e5229ca65713272fb4f2e354afbaab6a5791924a68b953216318a2347d1c70c"},{"code_id":"KoAP_RF","article_number":"5.35","version_date":"2001-12-30","article_text":"влечет предупреждение или наложение административного штрафа в размере от пятисот до двух тысяч рублей. (В редакции  федеральных законов от 22.06.2007 № 116-ФЗ, от 31.07.2025 № 302-ФЗ)\n\nвлечет наложение административного штрафа в размере от двух тысяч до трех тысяч рублей.\n\n(Дополнение частью - Федеральный закон от 04.05.2011 № 98-ФЗ)\n\nвлечет наложение административного штрафа в размере от четырех тысяч до пяти тысяч рублей или административный арест на срок до пяти суток.\n\n(Дополнение частью - Федеральный закон от 04.05.2011 № 98-ФЗ)","article_title":"Статья 5.35. Неисполнение родителями или иными законными представителями несовершеннолетних обязанностей по содержанию и воспитанию несовершеннолетних","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"920649ee12c969fe70eb4fdc704eafd947323c8767fd2c1e9b10d1b4c02a7a94"},{"code_id":"KoAP_RF","article_number":"5.351","version_date":"2001-12-30","article_text":"влечет обязательные работы на срок до ста пятидесяти часов либо административный арест на срок от десяти до пятнадцати суток или наложение административного штрафа на лиц, в отношении которых в соответствии с настоящим Кодексом не могут применяться обязательные работы либо административный арест, в размере двадцати тысяч рублей.\n\nвлечет обязательные работы на срок до ста пятидесяти часов либо административный арест на срок от десяти до пятнадцати суток или наложение административного штрафа на лиц, в отношении которых в соответствии с настоящим Кодексом не могут применяться обязательные работы либо административный арест, в размере двадцати тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 03.07.2016 № 326-ФЗ)","article_title":"Статья 5.351. Неуплата средств на содержание детей или нетрудоспособных родителей","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5fff96805e79aeeb8c83db3a4f4692d2dd05447168c1fc3d7b4c30e930505b2d"},{"code_id":"KoAP_RF","article_number":"5.36","version_date":"2001-12-30","article_text":"1. Нарушение руководителем учреждения, в котором находятся дети, оставшиеся без попечения родителей, либо должностным лицом органа исполнительной власти субъекта Российской Федерации или органа местного самоуправления порядка или сроков предоставления сведений о несовершеннолетнем, нуждающемся в передаче на воспитание в семью (на усыновление (удочерение), под опеку (попечительство) или в приемную семью) либо в учреждение для детей-сирот или для детей, оставшихся без попечения родителей, а равно предоставление заведомо недостоверных сведений о таком несовершеннолетнем -\n\nвлечет наложение административного штрафа в размере от одной тысячи до одной тысячи пятисот рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n2. Совершение руководителем учреждения, в котором находятся дети, оставшиеся без попечения родителей, либо должностным лицом органа исполнительной власти субъекта Российской Федерации или органа местного самоуправления действий, направленных на укрытие несовершеннолетнего от передачи на воспитание в семью (на усыновление (удочерение), под опеку (попечительство) или в приемную семью) либо в учреждение для детей-сирот или для детей, оставшихся без попечения родителей, -\n\nвлечет наложение административного штрафа в размере от двух тысяч до трех тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.36. Нарушение порядка или сроков предоставления сведений о несовершеннолетних, нуждающихся в передаче на воспитание в семью либо в учреждения для детей-сирот или для детей, оставшихся без попечения родителей","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"140153560080a0e9d5fd819db6a76015b00e5f6767f0e1ace61ad2d108068d81"},{"code_id":"KoAP_RF","article_number":"5.37","version_date":"2001-12-30","article_text":"Незаконные действия по усыновлению (удочерению) ребенка, передаче его под опеку (попечительство) или в приемную семью -\n\nвлекут наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч пятисот рублей; на должностных лиц - от четырех тысяч до пяти тысяч рублей; на юридических лиц - от двухсот тысяч до пятисот тысяч рублей. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ; от 05.04.2013 № 58-ФЗ)","article_title":"Статья 5.37. Незаконные действия по усыновлению (удочерению) ребенка, передаче его под опеку (попечительство) или в приемную семью","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9e96ed6987f6ecf44ee83baf15ab3aac4a3eaaa1e95b47112488943d791c980d"},{"code_id":"KoAP_RF","article_number":"5.38","version_date":"2001-12-30","article_text":"Воспрепятствование организации или проведению собрания, митинга, демонстрации, шествия или пикетирования, проводимых в соответствии с законодательством Российской Федерации, либо участию в них, а равно принуждение к участию в них -\n\nвлечет наложение административного штрафа на граждан в размере от десяти тысяч до двадцати тысяч рублей; на должностных лиц - от тридцати тысяч до пятидесяти тысяч рублей. (В редакции Федерального закона от 08.06.2012 № 65-ФЗ)","article_title":"Статья 5.38. Нарушение законодательства о собраниях, митингах, демонстрациях, шествиях и пикетировании","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"25fa6df9b658e2899fcd29cdfbca30a27d41ce32ed1616543c1cd7012706d1b0"},{"code_id":"KoAP_RF","article_number":"5.39","version_date":"2001-12-30","article_text":"Неправомерный отказ в предоставлении гражданину, в том числе адвокату в связи с поступившим от него адвокатским запросом, и (или) организации информации, предоставление которой предусмотрено федеральными законами, несвоевременное ее предоставление либо предоставление заведомо недостоверной информации - (В редакции Федерального закона от 02.06.2016 № 160-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до десяти тысяч рублей. (В редакции Федерального закона от 01.07.2017 № 146-ФЗ)\n\n(Статья в редакции Федерального закона от 31.05.2010 № 108-ФЗ)","article_title":"Статья 5.39. Отказ в предоставлении информации","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8125f285bf910e3a1af7708288d87eb62644ffe9569253a92c416231a6aeada1"},{"code_id":"KoAP_RF","article_number":"5.4","version_date":"2001-12-30","article_text":"Нарушение установленного законом порядка представления сведений об избирателях, участниках референдума либо представление недостоверных сведений об избирателях, участниках референдума соответствующим избирательным комиссиям должностным лицом, на которое законом возложена эта обязанность, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от одной тысячи до пяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Статья в редакции Федерального закона от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.4. Нарушение порядка представления сведений об избирателях, участниках референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a73b75916c37d7766d9bfceb5e6715a3b14be045f55d57e670e9c439b3c1182f"},{"code_id":"KoAP_RF","article_number":"5.40","version_date":"2001-12-30","article_text":"Принуждение к участию или к отказу от участия в забастовке путем насилия или угроз применения насилия либо с использованием зависимого положения принуждаемого -\n\nвлечет наложение административного штрафа на граждан в размере от пятисот до одной тысячи рублей; на должностных лиц - от одной тысячи до двух тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.40. Принуждение к участию или к отказу от участия в забастовке","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"401db1ce923cc01c210257e0d2ce3a96b405b7caa0e197ee0cb02496934f97cc"},{"code_id":"KoAP_RF","article_number":"5.41","version_date":"2001-12-30","article_text":"Непредоставление на безвозмездной основе услуг, предусмотренных гарантированным перечнем услуг по погребению, а равно невыплата социального пособия на погребение супругу, близким родственникам, иным родственникам, законному представителю умершего или иному лицу, взявшему на себя обязанность осуществить погребение умершего, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двух тысяч до пяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.41. Непредоставление на безвозмездной основе услуг по погребению, невыплата социального пособия на погребение","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c76ef970ce9e54e1abe18e9fd31963a42b8c0c960bde0f65230d191ed0995a2c"},{"code_id":"KoAP_RF","article_number":"5.42","version_date":"2001-12-30","article_text":"1. Неисполнение работодателем обязанности по выполнению квоты для приема на работу инвалидов, за исключением случаев освобождения работодателя от выполнения установленной квоты, либо отказ работодателя в приеме на работу инвалида в пределах установленной квоты -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до тридцати тысяч рублей; на индивидуальных предпринимателей - от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n(Часть в редакции  Федерального закона от 09.11.2024 № 382-ФЗ)\n\n2. Необоснованный отказ в регистрации инвалида в качестве безработного -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до десяти тысяч рублей.\n\n(Статья в редакции Федерального закона от 23.02.2013 № 11-ФЗ)","article_title":"Статья 5.42. Нарушение прав инвалидов в области трудоустройства и занятости","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"00567ff0e7b7b35a599f0bc090dffe9cf6fae5911b48fa63da5b770b0bc22ac3"},{"code_id":"KoAP_RF","article_number":"5.43","version_date":"2001-12-30","article_text":"Нарушение требований законодательства, предусматривающих выделение на автомобильных стоянках (остановках) мест для специальных автотранспортных средств инвалидов, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч до пяти тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ; от 04.06.2011 № 127-ФЗ)","article_title":"Статья 5.43. Нарушение требований законодательства, предусматривающих выделение на автомобильных стоянках (остановках) мест для специальных автотранспортных средств инвалидов","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0835ed6c867f16f475f49f19a604c96cd087387debed45fa3f17c09cc1889605"},{"code_id":"KoAP_RF","article_number":"5.44","version_date":"2001-12-30","article_text":"(Статья утратила силу - Федеральный закон от 24.07.2009 № 213-ФЗ)","article_title":"Статья 5.44. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"098c64930db4540e08e8e36b98f8459df71c522fd32cf3bd945ef1a9adab7ae6"},{"code_id":"KoAP_RF","article_number":"5.45","version_date":"2001-12-30","article_text":"Использование лицом, замещающим государств\n\nенную или муниципальную должность, либо находящимся на государственной или муниципальной службе, либо являющимся членом органа управления организации независимо от формы собственности (в организации, высшим органом управления которой является собрание, - членом органа, осуществляющего руководство деятельностью этой организации), за исключением политической партии, преимуществ своего должностного или служебного положения в целях выдвижения и (или) избрания кандидата, списка кандидатов, выдвижения и (или) поддержки инициативы проведения референдума, получения того или иного ответа на вопрос (вопросы) референдума -  (В редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nвлечет наложение административного штрафа в размере от трех тысяч до пяти тысяч рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.45. Использование преимуществ должностного или служебного положения в период избирательной кампании, кампании референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"871253231a6a6a87e5455fd867de383ab02c81381ca06593eb2603dc4f618086"},{"code_id":"KoAP_RF","article_number":"5.46","version_date":"2001-12-30","article_text":"Подделка подписей избирателей, участников референдума, собираемых в поддержку выдвижения кандидата, списка кандидатов, инициативы проведения референдума, а равно заверение заведомо подделанных подписей (подписных листов) лицом, осуществляющим сбор подписей избирателей, либо уполномоченным лицом, если эти действия не содержат уголовно наказуемого деяния, - (В редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nвлечет наложение административного штрафа в размере от двух тысяч до двух тысяч пятисот рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.46. Подделка подписей избирателей, участников референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e8cab9f81ef1347eb625427507feae8e5a9f2ec9ca51df0ceefb330d80abd24c"},{"code_id":"KoAP_RF","article_number":"5.47","version_date":"2001-12-30","article_text":"Участие органов государственной власти, органов местного самоуправления, органов управления организаций независимо от формы собственности, учреждений, членов избирательных комиссий с правом решающего голоса в сборе подписей избирателей в поддержку выдвижения кандидата, списка кандидатов, в сборе подписей участников референдума в поддержку инициативы проведения референдума, а равно сбор подписей на рабочих местах, в процессе и в местах выдачи заработной платы, пенсий, пособий, иных социальных выплат, а также при оказании благотворительной помощи - (В редакции федеральных законов от 21.07.2005 № 93-ФЗ; от 09.03.2016 № 66-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч рублей; на должностных лиц - от двух тысяч до трех тысяч рублей; на юридических лиц - от десяти тысяч до двадцати тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.47. Сбор подписей избирателей, участников референдума в запрещенных местах, а также сбор подписей лицами, которым участие в этом запрещено федеральным законом","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"05af4d89ef6610d2610c094b8fefaf4b34fdcc1d8f297c696aa0f8d9fafde13a"},{"code_id":"KoAP_RF","article_number":"5.48","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nНарушение прав зарегистрированных кандидатов, избирательных объединений, инициативных групп по проведению референдума, иных групп участников референдума на размещение агитационных материалов на объекте, находящемся в государственной или муниципальной собственности либо в собственности организации, в уставном (складочном) капитале которой доля (вклад) Российской Федерации, субъектов Российской Федерации и (или) муниципальных образований на день официального опубликования (публикации) решения о назначении выборов, регистрации инициативной группы по проведению референдума превышает 30 процентов, а равно нарушение организациями, оказывающими рекламные услуги, условий размещения агитационных материалов - (В редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц в размере от двух тысяч пятисот до трех тысяч рублей; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.48. Нарушение прав зарегистрированных кандидатов, избирательных объединений, инициативных групп по проведению референдума, иных групп участников референдума при выделении площадей для размещения агитационных материалов","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eb10ad53b161ebb5edd4be4c11217294638eb2aa220346f0102ac05dfa502071"},{"code_id":"KoAP_RF","article_number":"5.49","version_date":"2001-12-30","article_text":"Нарушение запрета на проведение в период избирательной кампании, кампании референдума лотерей и других основанных на риске игр, в которых выигрыш призов или участие в розыгрыше призов зависит от итогов голосования, результатов выборов, референдума либо которые иным образом связаны с выборами, референдумом, -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до двух тысяч пятисот рублей; на должностных лиц - от трех тысяч до пяти тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ) (В редакции Федерального закона от 21.07.2005 № 93-ФЗ)","article_title":"Статья 5.49. Нарушение запрета на проведение в период избирательной кампании, кампании референдума лотерей и других основанных на риске игр, связанных с выборами и референдумом","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"681e9a1779a514650a78264407ec18adaa9030ec9785cdf2f284cbcff10fffad"},{"code_id":"KoAP_RF","article_number":"5.5","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 01.04.2020 № 90-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от пятисот до двух тысяч пятисот рублей, на должностных лиц - от одной тысячи до пяти тысяч рублей; на юридических лиц - от тридцати тысяч до ста тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч до четырех тысяч рублей; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение частью - Федеральный закон от 21.07.2005 № 93-ФЗ)\n\n(Статья в редакции Федерального закона от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.5. Нарушение порядка участия средств массовой информации в информационном обеспечении выборов, референдумов, общероссийского голосования","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b96d9e3cad74390866656359f7c452c0d76e7e03944bfedcabba140d9b3c2094"},{"code_id":"KoAP_RF","article_number":"5.50","version_date":"2001-12-30","article_text":"Невозврат жертвователю в установленный законодательством о выборах и референдумах срок пожертвований (их части), перечисленных в избирательный фонд, фонд референдума с нарушением требований законодательства о выборах и референдумах, неперечисление в указанный срок в доход соответствующего бюджета пожертвований, внесенных анонимными жертвователями, - (В редакции Федерального закона от 09.02.2009 № 3-ФЗ)\n\nвлечет наложение административного штрафа на кандидата, на лицо, являвшееся кандидатом, на лицо, избранное депутатом, на уполномоченного представителя по финансовым вопросам инициативной группы по проведению референдума, иной группы участников референдума в размере от десяти тысяч до двадцати тысяч рублей; на избирательное объединение - от ста тысяч до трехсот тысяч рублей. (В редакции федеральных законов от 21.07.2005 № 93-ФЗ; от 22.06.2007 № 116-ФЗ; от 24.11.2014 № 355-ФЗ)\n\nПримечание. (Примечание утратило силу - Федеральный закон от 21.07.2005 № 93-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.50. Нарушение правил перечисления средств, внесенных в избирательный фонд, фонд референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"040d415bdc82982059b80390bed81bf0c76872baae682e2ba6ef2e55caff66dc"},{"code_id":"KoAP_RF","article_number":"5.51","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ) (Утратила силу - Федеральный закон от 09.03.2016 № 66-ФЗ)","article_title":"Статья 5.51. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"60ff4c9d58e917c921753b72e13681d707a33e47ae708726f861a4ef55f9b030"},{"code_id":"KoAP_RF","article_number":"5.52","version_date":"2001-12-30","article_text":"Невыполнение уполномоченным на то должностным лицом требований об обеспечении зарегистрированным кандидатам, избирательным объединениям равных условий для проведения агитационных публичных мероприятий в случаях, когда обеспечение таких условий предусмотрено законом, либо иное нарушение предусмотренных законодательством о выборах прав зарегистрированного кандидата, избирательного объединения при проведении ими указанных мероприятий -\n\nвлечет наложение административного штрафа в размере от трех тысяч до пяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ) (В редакции Федерального закона от 21.07.2005 № 93-ФЗ)","article_title":"Статья 5.52. Невыполнение уполномоченным лицом требований законодательства о выборах об обеспечении кандидатам, избирательным объединениям равных условий для проведения агитационных публичных мероприятий","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8c4819af17bbb0800aad661eecb1c9090ed635efea4a11d80a4546cd9718d725"},{"code_id":"KoAP_RF","article_number":"5.53","version_date":"2001-12-30","article_text":"Незаконные действия по получению и (или) распространению информации, составляющей кредитную историю, если такие действия не содержат уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч пятисот рублей; на должностных лиц - от двух тысяч пятисот до пяти тысяч рублей или дисквалификацию на срок до трех лет; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 30.12.2004 № 219-ФЗ)","article_title":"Статья 5.53. Незаконные действия по получению и (или) распространению информации, составляющей кредитную историю","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a85aca8ca7118db3a491868e79743b11edcf5020463c1dfd616a97a06e64b157"},{"code_id":"KoAP_RF","article_number":"5.54","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 21.12.2013 № 375-ФЗ)\n\n1. Непроведение проверки или несвоевременное проведение по требованию субъекта кредитной истории проверки бюро кредитных историй информации, содержащейся в кредитной истории (кредитном отчете), -\n\nвлечет наложение административного штрафа на должностных лиц в размере от одной тысячи до двух тысяч пятисот рублей; на юридических лиц - от десяти тысяч до двадцати тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n2. Незаконный отказ бюро кредитных историй в исправлении недостоверной информации или неисполнение обязанности по исправлению недостоверной информации, содержащейся в кредитной истории (кредитном отчете), -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двух тысяч до пяти тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 30.12.2004 № 219-ФЗ)","article_title":"Статья 5.54. Неисполнение обязанности по проведению проверки и (или) исправлению недостоверной информации, содержащейся в кредитной истории (кредитном отчете)","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"167d595d0e085ba02a73cb8b1efb437702a16c2068b0101c1856217f80bc2bc7"},{"code_id":"KoAP_RF","article_number":"5.55","version_date":"2001-12-30","article_text":"Непредоставление бюро кредитных историй кредитного отчета, предоставление неполного или недостоверного кредитного отчета, а также несвоевременное предоставление кредитного отчета в случаях, если такое предоставление осуществляется или должно осуществляться в соответствии с Федеральным законом \"О кредитных историях\", -\n\nвлекут наложение административного штрафа на должностных лиц в размере от одной тысячи до двух тысяч пятисот рублей; на юридических лиц - от двадцати тысяч до пятидесяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 30.12.2004 № 219-ФЗ)","article_title":"Статья 5.55. Непредоставление кредитного отчета","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7ec40152a9d45f74f996e91e48266fcccfa69b3b9c34b4c06b5db97f9fc0553f"},{"code_id":"KoAP_RF","article_number":"5.56","version_date":"2001-12-30","article_text":"1. Непредставление председателем, заместителем председателя или секретарем избирательной комиссии, комиссии референдума в вышестоящую избирательную комиссию, комиссию референдума документов, связанных с подготовкой и проведением выборов, референдума, или их представление с нарушением установленных законом сроков -\n\nвлечет наложение административного штрафа в размере от двух тысяч до пяти тысяч рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n2. Уничтожение документов, связанных с подготовкой и проведением выборов, референдума, до истечения сроков их хранения, а также нарушение установленного порядка уничтожения таких документов -\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи пятисот до двух тысяч рублей; на должностных лиц - от двух тысяч до пяти тысяч рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 21.07.2005 № 93-ФЗ)","article_title":"Статья 5.56. Нарушение порядка и сроков представления и хранения документов, связанных с подготовкой и проведением выборов, референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"63fb0260b85e0a486f32051b839a5a08a7d3e28086df272379ff296005b74883"},{"code_id":"KoAP_RF","article_number":"5.57","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 02.07.2013 № 185-ФЗ)\n\n1. Нарушение или незаконное ограничение права на образование, выразившиеся в нарушении или ограничении права на получение общедоступного и бесплатного образования, а равно незаконные отказ в приеме в образовательную организацию либо отчисление (исключение) из образовательной организации -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от ста тысяч до двухсот тысяч рублей.\n\nвлечет наложение административного штрафа на должностных лиц в размере от десяти тысяч до тридцати тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\nвлечет дисквалификацию на срок от одного года до двух лет.\n\n(Дополнение статьей - Федеральный закон от 03.06.2009 № 104-ФЗ)","article_title":"Статья 5.57. Нарушение права на образование и предусмотренных законодательством об образовании прав и свобод обучающихся образовательных организаций","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"529b1d5f8fac3e3fea18a3a5c2b044e2c32f4f9901d2970b3093ff5a066fddb8"},{"code_id":"KoAP_RF","article_number":"5.58","version_date":"2001-12-30","article_text":"1. Нарушение установленного законодательством о выборах и референдумах порядка выдачи открепительного удостоверения либо невыполнение требования об изъятии открепительного удостоверения или отрывного талона открепительного удостоверения либо нарушение порядка использования специального знака (марки) при включении избирателя, участника референдума в список избирателей, участников референдума -\n\nвлечет наложение административного штрафа в размере от одной тысячи до двух тысяч пятисот рублей.\n\n2. Использование заведомо поддельных открепительного удостоверения или специального знака (марки) -\n\nвлечет наложение административного штрафа в размере от одной тысячи пятисот до трех тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 04.10.2010 № 263-ФЗ) (В редакции Федерального закона от 01.06.2017 № 104-ФЗ)","article_title":"Статья 5.58. Нарушение установленного законодательством о выборах и референдумах порядка выдачи открепительного удостоверения и невыполнение требований о его изъятии. Нарушение порядка использования специального знака (марки). Использование заведомо поддельных открепительного удостоверения или специального знака (марки)","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d9f87faabaedc2f6d2566aef1ecb3c938c39c9f352c0db5c7d5e84c01af1736b"},{"code_id":"KoAP_RF","article_number":"5.59","version_date":"2001-12-30","article_text":"Нарушение установленного законодательством Российской Федерации порядка рассмотрения обращений граждан, объединений граждан, в том числе юридических лиц, должностными лицами государственных органов, органов местного самоуправления, государственных и муниципальных учреждений и иных организаций, на которые возложено осуществление публично значимых функций, за исключением случаев, предусмотренных статьями 5.39, 5.63 настоящего Кодекса, -\n\nвлечет наложение административного штрафа в размере от пяти тысяч до десяти тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 11.07.2011 № 199-ФЗ) (В редакции Федерального закона от 07.05.2013 № 80-ФЗ)","article_title":"Статья 5.59. Нарушение порядка рассмотрения обращений граждан","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"29403ce81b9235438a5149a93717e7a4b94ea95be678e4369145a0dc80428c80"},{"code_id":"KoAP_RF","article_number":"5.6","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от пятисот до одной тысячи рублей; на должностных лиц - от одной тысячи до двух тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\nвлечет наложение административного штрафа в размере от одной тысячи пятисот до двух тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение частью - Федеральный закон от 21.07.2005 № 93-ФЗ)\n\n(Статья в редакции Федерального закона от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.6. Нарушение прав члена избирательной комиссии, комиссии референдума, наблюдателя, иностранного (международного) наблюдателя, доверенного лица или уполномоченного представителя кандидата, избирательного объединения, члена или уполномоченного представителя инициативной группы по проведению референдума, иной группы участников референдума либо представителя средства массовой информации","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c84aa3cbd76c9ef731609d65c28a411fb2f797f4b42af3efcf9674c5702fb916"},{"code_id":"KoAP_RF","article_number":"5.60","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 07.12.2011 № 420-ФЗ) (Утратила силу - Федеральный закон от 28.07.2012 № 141-ФЗ)","article_title":"Статья 5.60. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5f6bc7949f4430ff2d0c560808cc0bb87c3d467a7fce6c7d2b402a2edddb3e08"}]$law7d0041$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
